-- engine_test_cases : run ONCE in the Neon SQL editor (after asset-type-config.sql)
-- Moves the 162 test cases that used to live inside the calc-engine .cjs files into Postgres.
CREATE TABLE IF NOT EXISTS engine_test_cases
(
    engine            TEXT NOT NULL,
    "caseId"          TEXT NOT NULL,
    name              TEXT NOT NULL,
    inputs            JSONB NOT NULL,
    "expectedOutputs" JSONB NOT NULL DEFAULT '{}'::jsonb,
    "sortOrder"       INTEGER NOT NULL DEFAULT 0,
    active            BOOLEAN NOT NULL DEFAULT TRUE,
    PRIMARY KEY (engine, "caseId")
);

ON CONFLICT (engine, "caseId") DO NOTHING;

-- check (should be 162)
SELECT engine, count(*) FROM engine_test_cases GROUP BY engine ORDER BY engine;
